const MAX_SEARCH_QUERY_CHARACTERS = 1_500;
const MAX_SEARCH_QUERIES = 3;

export const profileSearchQueries = (instruction: string): string[] => {
  if (!instruction.trim()) return [];
  const queries = [instruction.slice(0, MAX_SEARCH_QUERY_CHARACTERS)];
  const seen = new Set(queries.map((query) => query.trim()));
  for (const excerpt of instruction.split(/(?<=[.!?;])\s+|[\r\n]+/u)) {
    const query = excerpt.trim().slice(0, MAX_SEARCH_QUERY_CHARACTERS);
    if (!query || seen.has(query.trim())) continue;
    queries.push(query);
    seen.add(query.trim());
    if (queries.length === MAX_SEARCH_QUERIES) break;
  }
  return queries;
};
